"""Convert a decomposition rule tag into regex notation.

    Parameters
    ----------
    tag_name : str
        Tag to convert to regex notation.
    tags : dict
        Tags to consider when converting to regex.

    Returns
    -------
    w : str
        Tag converted to regex notation. Empty if `tag_name` is not in `tags`.
    """
def tag_to_regex(tag_name: Any, tags: Any) -> object {
    w = '';
    if (tag_name in tags) {
        w = r'\b(' + '|'.join(tags[tag_name]) + r')\b';
    }
    return w;
}

"""Returns the version string for retrieving a framework version's specific config."""
def _version_for_config(version: Any, config: Any) -> object {
    if ("version_aliases" in config) {
        if (version in config["version_aliases"].keys()) {
            return config["version_aliases"][version];
        }
    }
    return version;
}

