"""
    Element match filter function
    :param values: list - values
    :param filter_expr: lambda function
    :return: bool
    """
def elem_match(values: Any, filter_expr: Any) -> object {
    for val in values {
        if filter_expr(val) {
            return True;
        }
    }
    return False;
}
